-- Run once in a new Supabase project's SQL editor.
create extension if not exists pgcrypto;
create table public.admins(user_id uuid primary key references auth.users(id) on delete cascade);
create table public.players(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz default now());
create table public.matches(id uuid primary key default gen_random_uuid(),match_date date not null,season int not null,opposition text not null,venue text not null,team_score text,result text not null,opposition_score text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table public.performances(id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches(id) on delete cascade,player_id uuid not null references public.players(id),runs int not null default 0,balls int not null default 0,was_out boolean not null default true,fours int not null default 0,sixes int not null default 0,balls_bowled int not null default 0,maidens int not null default 0,runs_conceded int not null default 0,wickets int not null default 0,catches int not null default 0,unique(match_id,player_id));
create table public.news(id uuid primary key default gen_random_uuid(),title text not null,category text not null default 'Club update',body text not null,image_url text,published_at date not null default current_date,is_published boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz default now());
create table public.photos(id uuid primary key default gen_random_uuid(),image_url text not null,caption text not null,taken_at date,created_by uuid references auth.users(id),created_at timestamptz default now());
alter table public.admins enable row level security;alter table public.players enable row level security;alter table public.matches enable row level security;alter table public.performances enable row level security;
alter table public.news enable row level security;alter table public.photos enable row level security;
create policy "Public read published news" on public.news for select using(is_published);create policy "Public read photos" on public.photos for select using(true);
create policy "Admins manage news" on public.news for all using(exists(select 1 from public.admins where user_id=auth.uid())) with check(exists(select 1 from public.admins where user_id=auth.uid()));
create policy "Admins manage photos" on public.photos for all using(exists(select 1 from public.admins where user_id=auth.uid())) with check(exists(select 1 from public.admins where user_id=auth.uid()));
create policy "Public read players" on public.players for select using(true);create policy "Public read matches" on public.matches for select using(true);create policy "Public read performances" on public.performances for select using(true);
create policy "Admins manage players" on public.players for all using(exists(select 1 from public.admins where user_id=auth.uid())) with check(exists(select 1 from public.admins where user_id=auth.uid()));
create policy "Admins manage matches" on public.matches for all using(exists(select 1 from public.admins where user_id=auth.uid())) with check(exists(select 1 from public.admins where user_id=auth.uid()));
create policy "Admins manage performances" on public.performances for all using(exists(select 1 from public.admins where user_id=auth.uid())) with check(exists(select 1 from public.admins where user_id=auth.uid()));
create or replace function public.overs_to_balls(v text) returns int language plpgsql immutable as $$declare p text[];begin p:=string_to_array(coalesce(nullif(v,''),'0'),'.');return (p[1]::int*6)+least(coalesce(p[2]::int,0),5);end$$;
create or replace function public.record_match_scorecard(scorecard jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare mid uuid;item jsonb;pid uuid;begin if not exists(select 1 from admins where user_id=auth.uid()) then raise exception 'Admin access required';end if;insert into matches(match_date,season,opposition,venue,team_score,opposition_score,result,created_by) values((scorecard->>'match_date')::date,(scorecard->>'season')::int,scorecard->>'opposition',scorecard->>'venue',scorecard->>'team_score',scorecard->>'opposition_score',scorecard->>'result',auth.uid()) returning id into mid;for item in select * from jsonb_array_elements(scorecard->'players') loop insert into players(name) values(trim(item->>'player_name')) on conflict(name) do update set name=excluded.name returning id into pid;insert into performances(match_id,player_id,runs,balls,was_out,fours,sixes,balls_bowled,maidens,runs_conceded,wickets,catches) values(mid,pid,coalesce((item->>'runs')::int,0),coalesce((item->>'balls')::int,0),coalesce((item->>'was_out')::boolean,true),coalesce((item->>'fours')::int,0),coalesce((item->>'sixes')::int,0),overs_to_balls(item->>'overs'),coalesce((item->>'maidens')::int,0),coalesce((item->>'runs_conceded')::int,0),coalesce((item->>'wickets')::int,0),coalesce((item->>'catches')::int,0));end loop;return mid;end$$;
create view public.batting_statistics as select p.id,p.name,m.season,count(*) as innings,count(*) filter(where not pf.was_out) as not_outs,sum(pf.runs) as runs,max(pf.runs) as high_score,round(sum(pf.runs)::numeric/nullif(count(*) filter(where pf.was_out),0),2) as average,sum(pf.balls) as balls,round(sum(pf.runs)*100.0/nullif(sum(pf.balls),0),2) as strike_rate,sum(pf.fours) as fours,sum(pf.sixes) as sixes from performances pf join players p on p.id=pf.player_id join matches m on m.id=pf.match_id group by p.id,p.name,m.season;
create view public.bowling_statistics as select p.id,p.name,m.season,sum(pf.balls_bowled) as balls_bowled,sum(pf.maidens) as maidens,sum(pf.runs_conceded) as runs_conceded,sum(pf.wickets) as wickets,round(sum(pf.runs_conceded)::numeric/nullif(sum(pf.wickets),0),2) as average,round(sum(pf.runs_conceded)*6.0/nullif(sum(pf.balls_bowled),0),2) as economy,round(sum(pf.balls_bowled)::numeric/nullif(sum(pf.wickets),0),2) as strike_rate from performances pf join players p on p.id=pf.player_id join matches m on m.id=pf.match_id group by p.id,p.name,m.season;
grant select on public.batting_statistics,public.bowling_statistics to anon,authenticated;grant execute on function public.record_match_scorecard(jsonb) to authenticated;
